typedef struct { int val; int cnt; } VC;

int cmp_vc(const void *a, const void *b) {
    return ((VC*)b)->cnt - ((VC*)a)->cnt;
}

// Returns top 2 by frequency from array arr of length len
// Stores in top[0], top[1]
void top2(int *arr, int len, VC *top) {
    // Use simple approach: sort and count
    int *sorted = malloc(len * sizeof(int));
    memcpy(sorted, arr, len * sizeof(int));
    // sort
    int cmp_int(const void *a, const void *b) { return *(int*)a - *(int*)b; }
    qsort(sorted, len, sizeof(int), cmp_int);

    VC vcs[200005]; int nv = 0;
    for (int i = 0; i < len; ) {
        int j = i; while (j < len && sorted[j] == sorted[i]) j++;
        vcs[nv].val = sorted[i]; vcs[nv].cnt = j - i; nv++; i = j;
    }
    qsort(vcs, nv, sizeof(VC), cmp_vc);
    top[0] = vcs[0];
    if (nv > 1) top[1] = vcs[1]; else { top[1].val = -1; top[1].cnt = 0; }
    free(sorted);
}

