typedef struct {
    int val;
    int cnt;
} Pair;

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static void top_two_from_sorted(int *arr, int m, Pair *first, Pair *second) {
    first->val = -1; first->cnt = 0;
    second->val = -1; second->cnt = 0;
    if (m == 0) return;

    int i = 0;
    while (i < m) {
        int j = i + 1;
        while (j < m && arr[j] == arr[i]) j++;
        int c = j - i;
        int v = arr[i];

        if (c > first->cnt) {
            *second = *first;
            first->val = v;
            first->cnt = c;
        } else if (c > second->cnt) {
            second->val = v;
            second->cnt = c;
        }
        i = j;
    }
}

