        // evenTop[0], evenTop[1] are the top 2 values in even positions

        int bestOddVal = oddTop[0], bestOddCnt = oddCount.getOrDefault(bestOddVal, 0);
        int bestEvenVal = evenTop[0], bestEvenCnt = evenCount.getOrDefault(bestEvenVal, 0);

        int ans;
        if (bestOddVal != bestEvenVal) {
            ans = n - bestOddCnt - bestEvenCnt;
        } else {
            // Option 1: keep best odd, use 2nd best even
