public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Pair {
        int value;
        int count;
        Pair(int value, int count) {
            this.value = value;
            this.count = count;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        HashMap<Integer, Integer> evenMap = new HashMap<>();
        HashMap<Integer, Integer> oddMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int x = fs.nextInt();
            if (i % 2 == 0) {
                evenMap.put(x, evenMap.getOrDefault(x, 0) + 1);
            } else {
                oddMap.put(x, oddMap.getOrDefault(x, 0) + 1);
            }
        }

        Pair[] evenTop = topTwo(evenMap);
        Pair[] oddTop = topTwo(oddMap);

        int half = n / 2;
        int answer;

        if (evenTop[0].value != oddTop[0].value) {
            answer = (half - evenTop[0].count) + (half - oddTop[0].count);
        } else {
            int option1 = (half - evenTop[0].count) + (half - oddTop[1].count);
            int option2 = (half - evenTop[1].count) + (half - oddTop[0].count);
            answer = Math.min(option1, option2);
        }

        System.out.println(answer);
    }

    static Pair[] topTwo(HashMap<Integer, Integer> map) {
        Pair first = new Pair(-1, 0);
        Pair second = new Pair(-1, 0);

        for (Map.Entry<Integer, Integer> e : map.entrySet()) {
            int value = e.getKey();
            int count = e.getValue();

            if (count > first.count) {
                second = first;
                first = new Pair(value, count);
            } else if (count > second.count) {
                second = new Pair(value, count);
            }
        }

        return new Pair[]{first, second};
    }
}

import sys
from collections import Counter

def top_two(counter):
    items = counter.most_common(2)
    if len(items) == 0:
        return (None, 0), (None, 0)
    if len(items) == 1:
        return items[0], (None, 0)
    return items[0], items[1]

