    (o1_val, o1_cnt), (o2_val, o2_cnt) = top_two(odd)

    half = n // 2

    if e1_val != o1_val:
        ans = (half - e1_cnt) + (half - o1_cnt)
    else:
        ans = min(
            (half - e1_cnt) + (half - o2_cnt),
            (half - e2_cnt) + (half - o1_cnt)
        )

